import java.util.*;
import java.io.*;

public class Main {
    static long[] lsc = new long[62], rsc = new long[62], rsc2 = new long[62];
    static char[] s = new char[62];
    static Map<Pair<Long, Integer>, Long> nm = new HashMap<>();
    static Map<Pair<Long, Integer>, Long> mm = new HashMap<>();

    static long comb(int n, int k) {
        if (n < k || k < 0)
            return 0;
        long rez = 1;
        for (int i = 0; i < k; i++) {
            rez = rez * (n - i) / (i + 1);
        }
        return rez;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int r = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int n = 2 * (r + c);
        String line = br.readLine();
        s = line.toCharArray();

        lsc[2 * r - 1] = 1;
        for (int i = 2 * r; i < n; i++) {
            lsc[i] = lsc[i - 1] * i / (i - 2 * r + 1);
        }

        for (int i = 0; i <= n; i++) {
            rsc[i] = comb(i, r);
            rsc2[i] = comb(i, r - 1);
        }

        long msum = rsc[n / 2] * rsc[n / 2];
        for (int i = n - 1; i >= 0; i--) {
            int ok;
            if (msum > 0)
                ok = 1;
            else
                ok = 0;
            if (c == n / 2)
                ok = 1;
            if (r == n / 2)
                ok = 0;
            if (ok != 0) {
                r--;
                msum = msum - rsc2[n / 2 - r] * rsc[n / 2 - c];
            } else {
                c--;
                msum = msum + rsc2[n / 2 - c] * rsc[n / 2 - r];
            }
        }
        msum = Math.max(msum, -msum);
        Pair<Long, Integer> startPair = new Pair<>(0L, 0);
        mm.put(startPair, 1L);
        long nsum = 0;
        for (int i = n - 1; i >= 2 * r - 1; i--) {
            nm.clear();
            for (Map.Entry<Pair<Long, Integer>, Long> entry : mm.entrySet()) {
                long sum = entry.getKey().first;
                int cnt = entry.getKey().second;
                long ncnt = entry.getValue();
                int ast = n / 2 - cnt;
                int bst = i + 1 - ast;
                long asum = sum + rsc2[ast - 1] * rsc[bst];
                long bsum = sum - rsc2[bst - 1] * rsc[ast];
                if (s[i] == 'A') {
                    Pair<Long, Integer> key = new Pair<>(asum, cnt + 1);
                    nm.put(key, nm.getOrDefault(key, 0L) + ncnt);
                    Pair<Long, Integer> key2 = new Pair<>(bsum, cnt);
                    nm.put(key2, nm.getOrDefault(key2, 0L));
                } else if (s[i] == 'B') {
                    Pair<Long, Integer> key = new Pair<>(asum, cnt + 1);
                    nm.put(key, nm.getOrDefault(key, 0L));
                    Pair<Long, Integer> key2 = new Pair<>(bsum, cnt);
                    nm.put(key2, nm.getOrDefault(key2, 0L) + ncnt);
                } else {
                    Pair<Long, Integer> key1 = new Pair<>(asum, cnt + 1);
                    nm.put(key1, nm.getOrDefault(key1, 0L) + ncnt);
                    Pair<Long, Integer> key2 = new Pair<>(bsum, cnt);
                    nm.put(key2, nm.getOrDefault(key2, 0L) + ncnt);
                }
            }
            nsum = nsum - lsc[i];
            mm.clear();
            for (Map.Entry<Pair<Long, Integer>, Long> entry : nm.entrySet()) {
                long sum = entry.getKey().first;
                int cnt = entry.getKey().second;
                int ast = n / 2 - cnt;
                int bst = i - ast;
                if (cnt > n / 2 || n - i - cnt > n / 2)
                    continue;
                long lowerBound = -msum - rsc[ast] * rsc[bst];
                long upperBound = msum + rsc[ast] * rsc[bst];
                if (sum < lowerBound || sum > upperBound)
                    continue;
                Pair<Long, Integer> key = new Pair<>(sum, cnt);
                mm.put(key, mm.getOrDefault(key, 0L) + entry.getValue());
            }
        }
        long bsum = Long.MAX_VALUE;
        for (Map.Entry<Pair<Long, Integer>, Long> entry : mm.entrySet()) {
            long val = Math.max(entry.getKey().first, -entry.getKey().first);
            bsum = Math.min(bsum, val);
        }
        long rasp = 0;
        for (Map.Entry<Pair<Long, Integer>, Long> entry : mm.entrySet()) {
            long sum = entry.getKey().first;
            long ncnt = entry.getValue();
            int cnt = entry.getKey().second;
            if (sum == bsum || sum == -bsum) {
                int sem = 0;
                for (int i = 0; i < 2 * r - 1; i++) {
                    if (s[i] == '?')
                        sem++;
                    else if (s[i] == 'A')
                        cnt++;
                }
                ncnt = ncnt * comb(sem, n / 2 - cnt);
                rasp += ncnt;
            }
        }
        System.out.println(rasp);
    }

    static class Pair<F, S> {
        public F first;
        public S second;

        public Pair(F first, S second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair<?, ?> pair = (Pair<?, ?>) o;
            return Objects.equals(first, pair.first) && Objects.equals(second, pair.second);
        }

        @Override
        public int hashCode() {
            return Objects.hash(first, second);
        }
    }
